/**
 * Signals in message COMMAND.
 *
 * FUNCTION INDEX
 *
 * All signal values are as on the CAN bus.
 */
struct ter_command_t {
    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cmd;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t onoff;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint32_t value;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cfg_limiter;

    /**
     * Range: 1..120 (1..120 kW)
     * Scale: 1
     * Offset: 0
     */
    uint8_t kw_limit;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cfg_mode;

    /**
     * Range: 1..180 (1..180 N/m)
     * Scale: 1
     * Offset: 0
     */
    uint8_t trq_limit;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cfg_traction_control;

    /**
     * Range: 1..120 (1..120 km/h)
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_limit;
};

